using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.TKT.ComentariosTicket{    [SwaggerSchema("Modelo de lectura de un ComentariosTicket")]    [GraphQLDescription("Objeto que representa un ComentariosTicket existente.")]    public class clReadComentariosTicket    {        [SwaggerSchema("Identificador único del ComentariosTicket")]        [GraphQLDescription("Identificador único del ComentariosTicket")]        public int? ComentarioTicketID { get; set; }        [SwaggerSchema("TicketID")]        [GraphQLDescription("TicketID")]        public int? TicketID { get; set; }        [SwaggerSchema("UsuarioID")]        [GraphQLDescription("UsuarioID")]        public int? UsuarioID { get; set; }        [SwaggerSchema("Comentario")]        [GraphQLDescription("Comentario")]        public string? Comentario { get; set; } = default!;        [SwaggerSchema("FechaComentario")]        [GraphQLDescription("FechaComentario")]        public DateTime? FechaComentario { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un ComentariosTicket")]    [GraphQLDescription("Input para crear un ComentariosTicket.")]    public class clCreateComentariosTicket    {        [GraphQLNonNullType] [SwaggerSchema("TicketID")]        [GraphQLDescription("TicketID")]        public int TicketID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("UsuarioID")]        [GraphQLDescription("UsuarioID")]        public int UsuarioID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Comentario")]        [GraphQLDescription("Comentario")]        public string Comentario { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("FechaComentario")]        [GraphQLDescription("FechaComentario")]        public DateTime FechaComentario { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un ComentariosTicket")]    [GraphQLDescription("Input para actualizar parcialmente un ComentariosTicket.")]    public class clUpdateComentariosTicket    {        [SwaggerSchema("Identificador único del ComentariosTicket")]        [GraphQLDescription("Identificador único del ComentariosTicket")]        public int? ComentarioTicketID { get; set; }        [SwaggerSchema("TicketID")]        [GraphQLDescription("TicketID")]        public int? TicketID { get; set; }        [SwaggerSchema("UsuarioID")]        [GraphQLDescription("UsuarioID")]        public int? UsuarioID { get; set; }        [SwaggerSchema("Comentario")]        [GraphQLDescription("Comentario")]        public string? Comentario { get; set; }        [SwaggerSchema("FechaComentario")]        [GraphQLDescription("FechaComentario")]        public DateTime? FechaComentario { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}